addpath('functions');

[s, h, sizes] = loadRuns('gdfs/ah7.20170613.161402.offline.mi.mi_bhbf.gdf'); %[output:8a7238cb]
fs = h.SampleRate;

% dim s = 172032x17
% 17 (16+1) channels, the 17th is the trigger
% sample frequency = 512 Hz
% recording is 172032/512 = 336 s long
fprintf('Samples: %d, channels: %d, fs: %d Hz, duration: %.1f s\n', ... %[output:group:3e941177] %[output:7343bf2c]
    size(s, 1), size(s, 2), fs, size(s, 1) / fs); %[output:group:3e941177] %[output:7343bf2c]
assert(size(s, 1) == sum(sizes));
%%
figure; %[output:1e51f3da]
channel1 = s(:, 1);
interval = 1:5*fs;
plot(interval ./ fs, channel1(interval)); %[output:1e51f3da]
title('EEG Channel #1'); %[output:1e51f3da]
xlabel('seconds [s]'); %[output:1e51f3da]
ylabel('Amplitude [uV]'); %[output:1e51f3da]
%%
figure; %[output:13a7a4f0]
for i = 1:3 %[output:group:3f6e99d8]
    subplot(3, 1, i); %[output:13a7a4f0]
    interval = 1:5*fs;
    plot(interval ./ fs, s(interval, i));
    title(sprintf('EEG Channel #%d', i));
    xlabel('seconds [s]');
    ylabel('Amplitude [uV]');
    ylim([-80, 80]);
end %[output:group:3f6e99d8]
%%
figure; %[output:8590f54b]
ax = subplot(1, 1, 1); %[output:8590f54b]
hold(ax, 'on'); %[output:8590f54b]
interval = 1:5*fs;
for i = 1:3
    plot(ax, interval ./ fs, s(interval, i), 'DisplayName', sprintf('Chn #%d', i)); %[output:8590f54b]
end
title(ax, 'EEG Channel #1..3'); %[output:8590f54b]
xlabel(ax, 'seconds [s]'); %[output:8590f54b]
ylabel(ax, 'Amplitude [uV]'); %[output:8590f54b]
ylim(ax, [-80, 80]); %[output:8590f54b]
legend(ax, 'show'); %[output:8590f54b]
hold(ax, 'off'); %[output:8590f54b]
%%
fprintf('Number of events: %d\n', size(h.EVENT.POS, 1)); %[output:2be4ec33]
fprintf('About the 1st event:\n'); %[output:234ef289]
fprintf(' - Event type: %d\n', h.EVENT.TYP(1)); %[output:76e6785a]
fprintf(' - Event duration: %f s\n', h.EVENT.DUR(1) / fs); %[output:542becf6]
fprintf(' - Event is in [%f, %f] s\n', h.EVENT.POS(1) / fs, (h.EVENT.POS(1) + h.EVENT.DUR(1)) / fs); %[output:9d851bb2]
%%
START_PLOT = 30;
END_PLOT = 55;

interval = START_PLOT*fs:END_PLOT*fs;
x = interval ./ fs;

figure('Position', [100 100 1000 1000]); %[output:00f8d308]

for i = 1:3 %[output:group:9c6c06fb]
    ax = subplot(3, 1, i); %[output:00f8d308]
    plotEvents(ax, h, fs, [START_PLOT END_PLOT], [-80 80]);
    plot(ax, x, s(interval, i), 'b', 'HandleVisibility', 'off');
    title(ax, sprintf("EEG Channel #%d in [%d,%d]s", i, START_PLOT, END_PLOT));
    xlabel(ax, 'seconds [s]');
    ylabel(ax, 'Amplitude [uV]');
    hold(ax, 'off');
end %[output:group:9c6c06fb]
%%
codes = double(h.EVENT.TYP(:));
[u, ~, idx] = unique(codes);
counts = accumarray(idx, 1);

disp(table(u, counts, 'VariableNames', {'Code', 'Count'})) %[output:3f8b41ad]
%%
% Sample-wise labels: Tk (trial), Fk (fixation), Ak (cue), CFk (feedback),
% Xk (outcome), Rk (run, here always 1). All are [samples x 1].
lbl = labelEvents(h, sizes);

% Validate: transitions must follow start -> fixation -> cue -> feedback
START_PLOT = 30;
END_PLOT = 55;
interval = START_PLOT*fs:END_PLOT*fs;

figure; %[output:51fd6efd]
ax = subplot(1, 1, 1); %[output:51fd6efd]
hold(ax, 'on'); %[output:51fd6efd]
plot(ax, interval ./ fs, lbl.Fk(interval), 'DisplayName', 'Fk'); %[output:51fd6efd]
plot(ax, interval ./ fs, lbl.Ak(interval), 'DisplayName', 'Ak'); %[output:51fd6efd]
plot(ax, interval ./ fs, lbl.CFk(interval), 'DisplayName', 'CFk'); %[output:51fd6efd]
plot(ax, interval ./ fs, lbl.Xk(interval), 'DisplayName', 'Xk'); %[output:51fd6efd]
plot(ax, interval ./ fs, lbl.Tk(interval) * 100, 'DisplayName', 'Tk x100'); %[output:51fd6efd]
hold(ax, 'off'); %[output:51fd6efd]
xlabel(ax, 'seconds [s]'); %[output:51fd6efd]
legend(ax, 'show', 'Location', 'bestoutside'); %[output:51fd6efd]
title(ax, sprintf('Label vectors in [%d,%d]s', START_PLOT, END_PLOT)); %[output:51fd6efd]
%%
% Trials: [samples x channels x trials], Ck: cue of each trial.
[trials, Ck, RunTrial, info] = extractTrials(s(:, 1:16), lbl, MaxLengthDiff=5);

nTrials = size(trials, 3);
fprintf('Number of trials: %d (Tk max = %d)\n', nTrials, max(lbl.Tk)); %[output:00060701]
fprintf('Trial length: %d..%d samples -> kept %d samples (%.3f s)\n', ... %[output:group:95c744c2] %[output:2ba5b771]
    info.minLength, info.maxLength, size(trials, 1), size(trials, 1) / fs); %[output:group:95c744c2] %[output:2ba5b771]
assert(nTrials == nnz(h.EVENT.TYP == 1));
assert(all(ismember(Ck, [771 773])));
%%
channel = 7; % C3
t = (0:size(trials, 1)-1) ./ fs; % time from trial start
cues = [771 773];

figure; %[output:3aed1155]
for c = 1:numel(cues) %[output:group:5cc7d4d2]
    ax = subplot(2, 1, c); %[output:3aed1155]
    hold(ax, 'on');
    for i = find(Ck == cues(c))'
        plot(ax, t, trials(:, channel, i));
    end
    hold(ax, 'off');
    title(ax, sprintf('Cue %d - Channel %d - all trials', cues(c), channel));
    xlabel(ax, 'time from trial start [s]');
    ylabel(ax, 'Amplitude [uV]');
    xlim(ax, [0, t(end)]);
end %[output:group:5cc7d4d2]
%%
[avg, counts] = cueAverage(trials, Ck, cues);

figure; %[output:486a346a]
ax = subplot(1, 1, 1); %[output:486a346a]
hold(ax, 'on'); %[output:486a346a]
for c = 1:numel(cues)
    plot(ax, t, avg(:, channel, c), 'DisplayName', sprintf('Cue %d (%d trials)', cues(c), counts(c))); %[output:486a346a]
end
hold(ax, 'off'); %[output:486a346a]
title(ax, sprintf('Cue 771 vs 773 on Channel %d', channel)); %[output:486a346a]
xlabel(ax, 'time from trial start [s]'); %[output:486a346a]
ylabel(ax, 'Amplitude [uV]'); %[output:486a346a]
legend(ax, 'show'); %[output:486a346a]
xlim(ax, [0, t(end)]); %[output:486a346a]
%%
% Single trials vs grand average, first 3 trials of each cue
N_EXAMPLES = 3;

figure('Position', [100 100 1200 800]); %[output:4309373a]
ax = gobjects(N_EXAMPLES, numel(cues));
for c = 1:numel(cues)
    v = find(Ck == cues(c));
    for i = 1:N_EXAMPLES
        ax(i, c) = subplot(N_EXAMPLES, numel(cues), (i - 1) * numel(cues) + c); %[output:4309373a]
        hold(ax(i, c), 'on');
        plot(ax(i, c), t, trials(:, channel, v(i)), 'DisplayName', sprintf('Trial #%d', v(i)));
        plot(ax(i, c), t, avg(:, channel, c), 'DisplayName', 'Mean');
        hold(ax(i, c), 'off');
        title(ax(i, c), sprintf('Cue %d - Trial #%d', cues(c), v(i)));
        legend(ax(i, c), 'show', 'Location', 'best');
        xlim(ax(i, c), [0, t(end)]);
    end
end
linkaxes(ax(:), 'y'); % common amplitude scale %[output:4309373a]

